'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['moveCursor']);
const { moveCursor } = api;

const entries = ['first', 'second', 'third', 'fourth'];
const snapshot = entries.slice();
assert.deepStrictEqual(moveCursor(entries, 1, 0), { index: 1, value: 'second' });
assert.deepStrictEqual(moveCursor(entries, 2, -1), { index: 1, value: 'second' });
assert.deepStrictEqual(moveCursor(entries, 1, 2), { index: 3, value: 'fourth' });
assert.deepStrictEqual(moveCursor(entries, 2, -100), { index: 0, value: 'first' });
assert.deepStrictEqual(moveCursor(entries, 1, 100), { index: 3, value: 'fourth' });
assert.deepStrictEqual(moveCursor([], -1, -999), { index: -1, value: null });
assert.deepStrictEqual(moveCursor([], -1, 999), { index: -1, value: null });
assert.deepStrictEqual(entries, snapshot);

for (const value of [null, {}, 'entries', [1], ['ok', null]]) assert.throws(() => moveCursor(value, 0, 1), TypeError);
for (const index of [null, '0', 1.5, NaN, Infinity]) assert.throws(() => moveCursor(entries, index, 1), TypeError);
for (const displacement of [null, '1', 1.5, NaN, Infinity]) assert.throws(() => moveCursor(entries, 0, displacement), TypeError);
assert.throws(() => moveCursor([], 0, 1), RangeError);
assert.throws(() => moveCursor(entries, -1, 1), RangeError);
assert.throws(() => moveCursor(entries, entries.length, 1), RangeError);

